def parse_list(self, response):
    for li in response.css('ul li'):
        detail_url = li.css('a::attr(href)').get()
        if detail_url:
            yield response.follow(detail_url, callback=self.parse_detail)

code_snippets.parse_detail:
def parse_detail(self, response):
    title = response.css('h1::text').get() or response.css('title::text').get()
    pdf_urls = response.css('a[href$=".pdf"]::attr(href)').getall()
    for pdf_url in pdf_urls:
        yield {
            'title': title,
            'pdf_url': response.urljoin(pdf_url)
        }
        yield scrapy.Request(response.urljoin(pdf_url), callback=self.save_pdf)

def save_pdf(self, response):
    path = response.url.split('/')[-1]
    with open(path, 'wb') as f:
        f.write(response.body)
